def _construct_message_from_envelope(message: dict) -> BaseMessage:
    """Reconstruct a message object from a Serializable constructor envelope.

    Args:
        message: A dict in the constructor-envelope format (see
            `_is_message_envelope`).

    Returns:
        A message of the type indicated by the envelope's class name.

    Raises:
        ValueError: if the envelope references an unknown or unsupported class.
    """
    class_name = message["id"][-1]
    kwargs = dict(message["kwargs"])

    # Chunk variants are reconstructed as their parent message type.
    if class_name.endswith("Chunk"):
        class_name = class_name[: -len("Chunk")]

    if class_name == "HumanMessage":
        return HumanMessage(**kwargs)
    if class_name == "AIMessage":
        return AIMessage(**kwargs)
    if class_name == "SystemMessage":
        return SystemMessage(**kwargs)
    if class_name == "ToolMessage":
        additional_kwargs = kwargs.get("additional_kwargs") or {}
        if "artifact" not in kwargs and "artifact" in additional_kwargs:
            kwargs["artifact"] = additional_kwargs["artifact"]
        return ToolMessage(**kwargs)
    if class_name == "FunctionMessage":
        return FunctionMessage(**kwargs)

    msg = f"Unable to reconstruct message from envelope for class '{class_name}'."
    msg = create_message(message=msg, error_code=ErrorCode.MESSAGE_COERCION_FAILURE)
    raise ValueError(msg)


